  'Order in which HR accepts the requests, with no other priority. When a place frees up, Cursus offers HR the first person still eligible (contract, absences and other sessions on those days, certification still to renew); ': 'Ordre d’acceptation des demandes par le service RH, sans autre priorité. Quand une place se libère, Cursus propose au service RH le premier encore admissible (contrat, absences et autres sessions ces jours-là, certification toujours à renouveler) ; ',
