  'State of the modules of your team: status, progress and completion. Enrolments and approval: HR.': 'État des modules de votre équipe : statut, avancement et fin. Inscriptions et validation : service RH.',
  'The follow-up is limited to the status, the progress declared or imported, the completion date and the pass, with no connection time. The completion, approved by HR, creates the training followed and, for a module linked to the catalogue and passed, the certification; its hours count in the plan, never on the timesheet.': 'Le suivi se limite au statut, à l’avancement déclaré ou importé, à la date de fin et à la réussite, sans temps de connexion. La fin, validée par le service RH, crée la formation suivie et, pour un module rattaché au catalogue et réussi, la certification ; ses heures comptent dans le plan, jamais sur la feuille de temps.',
