  'lines': 'lignes',
  ' (Caisse des dépôts): export columns set in Settings → Prevention passport; the first name is the first word of the name on the sheet, to check for a compound first name. Cursus does not hold the NIR: matching by the payroll number in Sage. Offered are the certifications and training followed of the training courses ticked “Prevention passport” in Reference data → Training; a line marked declared is no longer offered. “Mark as declared” only ticks by default the lines of the last export. Training of a temp worker is in principle declared by the temporary work agency: it is set aside from the export.': ' (Caisse des dépôts) : colonnes de l’export réglées dans Paramètres → Passeport de prévention ; le prénom est le premier mot du nom de la fiche, à vérifier pour un prénom composé. Cursus ne détient pas le NIR : rapprochement par le matricule de paie dans Sage. Sont proposées les certifications et formations suivies des formations cochées « Passeport de prévention » dans Référentiels → Formations ; une ligne marquée déclarée ne l’est plus. « Marquer déclarées » ne coche d’office que les lignes du dernier export. Une formation d’intérimaire se déclare en principe par l’entreprise de travail temporaire : elle est écartée de l’export.',
