  'Withdraw': 'Retirer',
  'No absence matches these filters.': 'Aucune absence ne correspond à ces filtres.',
  'No absence planned.': 'Aucune absence prévue.',
  'Rules applied': 'Règles appliquées',
  'Paid leave: 25 working days a year, accrued at 2.08 d a month from 1 June to 31 May, rounded up to the next whole number.': 'Congés payés : 25 jours ouvrés par an, acquis à raison de 2,08 j par mois du 1er juin au 31 mai, arrondis à l’entier supérieur.',
  'Accrual during absences (law of 22 April 2024): work or commuting accident, occupational disease (with no limit of duration), maternity, paternity, adoption and family events count as actual work; ': 'Acquisition pendant les absences (loi du 22 avril 2024) : accident du travail ou de trajet, maladie professionnelle (sans limite de durée), maternité, paternité, adoption et événements familiaux comptent comme du travail effectif ; ',
  'sick leave also treated as actual work (more favourable agreement or CCN, Settings → Leave and closings)': 'arrêt maladie assimilé lui aussi à du travail effectif (accord ou CCN plus favorable, Paramètres → Congés et clôtures)',
  'sick leave: 2 working days (Mon–Sat) a month (1.67 working day), 24 working days (Mon–Sat) (20 Mon–Fri) per period at most': 'arrêt maladie : 2 jours ouvrables par mois (1,67 j ouvré), 24 jours ouvrables (20 ouvrés) par période au plus',
  '; an absence still to qualify counts as sickness. Parental leave, unpaid leave, unjustified absence and sick child reduce the month pro rata, unless 4 weeks or 24 working days (Mon–Sat) of work remain.': ' ; une absence encore à qualifier compte comme une maladie. Congé parental, sans solde, absence injustifiée et enfant malade réduisent le mois au prorata, sauf s’il reste 4 semaines ou 24 jours ouvrables de travail.',
  'Each day of leave is counted on the period whose entitlement is taken at its date (leave from May to June is split over two periods). Period used up: taken in advance on the days being accrued, within the limit of those accrued at the date of the leave, deducted from the next period on 1 June.': 'Chaque jour de congé est décompté sur la période dont les droits se prennent à sa date (un congé de mai à juin est réparti sur deux périodes). Période épuisée : prise par anticipation sur les jours en cours d’acquisition, dans la limite de ceux acquis à la date du congé, déduits de la période suivante au 1er juin.',
  'CCN Chemical industries: no seniority leave; +5 working days from age 59.': 'CCN Industries chimiques : pas de congés d’ancienneté ; +5 jours ouvrés à partir de 59 ans.',
  'Annual fixed days: rest days calculated individually according to the number of days of the fixed term (calendar days − weekends − 25 CP − working public holidays − days of the fixed term); ': 'Forfait annuel en jours : jours de repos calculés individuellement selon le nombre de jours du forfait (jours calendaires − week-ends − 25 CP − fériés ouvrés − jours du forfait) ; ',
  ' days in ': ' jours en ',
  ' for a fixed term of 218 days.': ' pour un forfait de 218 jours.',
  'Annual fixed hours: no RTT nor weekly compensatory rest; the hours beyond the fixed term are adjusted at year end.': 'Forfait annuel en heures : pas de RTT ni de repos compensateur hebdomadaire ; les heures au-delà du forfait sont régularisées en fin d’année.',
  'Weekly fixed hours: overtime included in the fixed term (beyond 35 h) paid at a premium in the pay; hours worked beyond the fixed term paid at a premium, or replaced by a compensatory rest when a collective agreement provides for it (Settings → Payroll).': 'Forfait hebdomadaire en heures : heures supplémentaires incluses au forfait (au-delà de 35 h) majorées dans la rémunération ; heures effectuées au-delà du forfait payées avec majoration, ou remplacées par un repos compensateur quand un accord collectif le prévoit (Paramètres → Paie).',
  'Senior executive (art. L3111-2): paid leave only — neither RTT nor compensatory rest.': 'Cadre dirigeant (art. L3111-2) : congés payés uniquement — ni RTT, ni repos compensateur.',
  'Part time: same right to leave; the CP count includes the days not worked in the period.': 'Temps partiel : même droit à congés ; le décompte des CP inclut les jours non travaillés de la période.',
  'Closing of paid leave, offered from 1 June: no day is lost automatically, HR decides for each employee to carry over the balance (capped at the balance, until the next 31 May) or to lose it. The days accrued during a health absence, a maternity, a paternity or an adoption, and those it prevented from taking, are carried over for 15 months (from the information of the employee on their return if it is later), within the limit of the balance. A carry-over granted during the period is applied at closing.': 'Clôture des congés payés, proposée à partir du 1er juin : aucun jour n’est perdu d’office, le service RH décide pour chaque salarié du report du solde (plafonné au solde, jusqu’au 31 mai suivant) ou de sa perte. Les jours acquis pendant une absence de santé, une maternité, une paternité ou une adoption, et ceux qu’elle a empêché de prendre, sont reportés de 15 mois (à compter de l’information du salarié à son retour si elle est plus tardive), dans la limite du solde. Un report accordé en cours de période est appliqué à la clôture.',
  'Return from sick leave or an accident: within the month, HR informs the employee of their days of leave and of the deadline to take them (“Information on return to give”); the 15-month carry-over runs from this information.': 'Retour d’un arrêt de maladie ou d’accident : dans le mois, le service RH informe le salarié de ses jours de congés et de la date limite pour les prendre (« Informations au retour à faire ») ; le report de 15 mois court à partir de cette information.',
  'RTT and rest days: not carried over, closed on 31 December (balances not taken lost, after the CET reminder). Those of the next year are requested from now on its own entitlement; a request spanning two years is refused.': 'RTT et jours de repos : non reportables, clôturés au 31 décembre (soldes non pris perdus, après le rappel du CET). Ceux de l’année suivante se posent dès maintenant sur son propre droit ; une demande à cheval sur deux années est refusée.',
  'Counters taken over from the former tool: counted on the CP period and the RTT year of their cut-off date, never beyond.': 'Compteurs repris de l’ancien outil : décomptés sur la période de CP et l’année de RTT de leur date d’arrêté, jamais au-delà.',
  'Time savings account: up to ': 'Compte épargne-temps : jusqu’à ',
  ' RTT a year (before 31 December) and ': ' RTT par an (avant le 31 décembre) et ',
  ' CP per period, only those of the 5th week (beyond 20 working days); caps set in Settings → Time savings account. The days saved are taken as leave on the CET (working days), approved by the manager like paid leave; paid out in full on leaving.': ' CP par période, uniquement ceux de la 5e semaine (au-delà de 20 jours ouvrés) ; plafonds réglés dans Paramètres → Compte épargne-temps. Les jours épargnés se prennent en congé sur le CET (jours ouvrés), validé par le manager comme un congé payé ; liquidés en entier à la sortie.',
  ' Cashing in open (agreement: ': ' Monétisation ouverte (accord : ',
  '): days coming from RTT only, ': ') : jours venus des RTT seulement, ',
  ' d a year at most, on request approved by HR.': ' j par an au plus, sur demande validée par le service RH.',
  ' Cashing in: not open (agreement to reference).': ' Monétisation : non ouverte (accord à référencer).',
  'Main leave: at least 12 consecutive working days (Mon–Sat) (10 Mon–Fri) between ': 'Congé principal : au moins 12 jours ouvrables continus (10 ouvrés) entre le ',
