  ', 24 working days (Mon–Sat) (20 Mon–Fri) in a row at most — flagged without blocking. ': ', 24 jours ouvrables (20 ouvrés) d’affilée au plus — signalés sans blocage. ',
  'Split days set aside by collective agreement.': 'Jours de fractionnement écartés par accord collectif.',
  'Split days: 2 days for 6 working days (Mon–Sat) or more of the main leave (5th week excluded) taken outside this period, 1 day for 3 to 5': 'Jours de fractionnement : 2 jours pour 6 jours ouvrables ou plus du congé principal (5e semaine exclue) pris hors de cette période, 1 jour pour 3 à 5',
  ', or the rule of the company agreement': ', ou la règle de l’accord d’entreprise',
  '; offered after the period, credited by HR or set aside by the employee’s waiver.': ' ; proposés après la période, crédités par le service RH ou écartés par la renonciation du salarié.',
  'Temp work: leave managed by the agency; fixed-term contract: compensatory allowance for the CP not taken at the end.': 'Intérim : congés gérés par l’agence ; CDD : indemnité compensatrice des CP non pris à l’échéance.',
  'Absences and timesheets stay within the bounds of the contract: start, end of the fixed-term contract, of the assignment or of the work-study.': 'Absences et feuilles de temps restent dans les bornes du contrat : entrée, fin du CDD, de la mission ou de l’alternance.',
  'Cancellation: the employee withdraws their pending request, or their own report as long as it is neither qualified nor extended; the manager or HR cancel an absence that has not started, HR alone an absence started or past. The balance is credited back and Keystone told; a timesheet submitted without hours that the absence covered is sent back for entry.': 'Annulation : le salarié retire sa demande en attente, ou son propre signalement tant qu’il n’est ni qualifié ni prolongé ; le manager ou le service RH annulent une absence qui n’a pas commencé, le service RH seul une absence commencée ou passée. Le solde est recrédité et Keystone prévenu ; une feuille soumise sans heure que l’absence couvrait est renvoyée pour saisie.',
  'Absences other than leave': 'Absences hors congés',
  'Minimum durations of the Labour Code · the CCN may be more favourable': 'Durées minimales du Code du travail · la CCN peut être plus favorable',
  'Pay': 'Rémunération',
