  'Visible to HR and the person concerned only, never to the manager.': 'Visible du service RH et de l’intéressé seulement, jamais du manager.',
  'The absence counts as soon as it is reported: no hours can be entered those days and Keystone receives the unavailability. HR then specifies its nature (sick leave, accident, family event…); a sick leave or the health of a child is communicated neither to the manager nor to Keystone. If the absence lasts longer, extend it from the list.': 'L’absence compte dès son signalement : aucune heure ne peut être saisie ces jours-là et Keystone reçoit l’indisponibilité. Le service RH précise ensuite sa nature (arrêt de travail, accident, événement familial…) ; un arrêt de travail ou la santé d’un enfant n’est communiqué ni au manager ni à Keystone. Si l’absence dure plus longtemps, prolongez-la depuis la liste.',
