  'The renewal is offered to the employee before the term of the contract and takes the form of a written amendment (art. L1243-13). The end of the contract becomes the new term: “End of fixed-term contract” due date, departure and pay period follow it. Nothing is blocked: check the contract and the industry agreement.': 'Le renouvellement est proposé au salarié avant le terme du contrat et prend la forme d’un avenant écrit (art. L1243-13). La fin du contrat devient le nouveau terme : échéance « Fin de CDD », sortie et période de paie la suivent. Rien n’est bloqué : vérifiez le contrat et l’accord de branche.',
