  'No approver changes: the approvals follow the managers and the parent teams. The site and the unit, when empty, are those of a team above (the site, failing that, that of the entity); those of the members follow and go to Matrix with their sheet. Unit code in the format of the Matrix organisation chart: PRD, PRD-MAINT, PRD-MAINT-EQ1.': 'Aucun valideur ne change : les validations suivent les managers et les équipes parentes. Le site et l’unité, vides, sont ceux d’une équipe au-dessus (le site, à défaut, celui de l’entité) ; ceux des membres suivent et partent à Matrix avec leur fiche. Code d’unité au format de l’organigramme de Matrix : PRD, PRD-MAINT, PRD-MAINT-EQ1.',
