  'Company of fewer than 300 employees, without an agreement on the BDESE: content of article R2312-9 of the Labour Code, over the years': 'Entreprise de moins de 300 salariés, sans accord sur la BDESE : contenu de l’article R2312-9 du Code du travail, sur les années',
  '. Cursus fills headings 1° (social investment) and 2° (gender equality at work) with what it knows; the rest is listed with its source. No social report under 300 employees (art. L2312-28).': '. Cursus remplit les rubriques 1° (investissement social) et 2° (égalité professionnelle) avec ce qu’il connaît ; le reste est listé avec sa source. Pas de bilan social sous 300 salariés (art. L2312-28).',
