  'Gender equality index ': 'Index d’égalité professionnelle ',
  'Missing data: pay and pay rises are in Sage, none enters Cursus. Indicators 1, 2 and 4 and the score are calculated in Sage or on Egapro; Cursus prepares the headcounts taken into account and the returns from maternity leave.': 'Données manquantes : les rémunérations et les augmentations sont dans Sage, aucune n’entre dans Cursus. Les indicateurs 1, 2 et 4 et la note se calculent dans Sage ou sur Egapro ; Cursus prépare les effectifs pris en compte et les retours de congé de maternité.',
  'Indicators of the gender equality index and their source': 'Indicateurs de l’index d’égalité professionnelle et leur source',
  'No.': 'N°',
  'Index of companies of 50 to 250 employees (art. L1142-8, D1142-2): publication by 1 March at the latest, declaration on Egapro, results filed in the BDESE. Groups of fewer than 3 people of one sex are excluded from indicator 1. Indicator 3: Cursus knows the returns from leave, not the pay rises.': 'Index des entreprises de 50 à 250 salariés (art. L1142-8, D1142-2) : publication au plus tard le 1er mars, déclaration sur Egapro, résultats versés à la BDESE. Les groupes de moins de 3 personnes d’un sexe sont exclus de l’indicateur 1. Indicateur 3 : Cursus connaît les retours de congé, pas les augmentations.',
  'Annual freezes': 'Arrêtés annuels',
  'Freeze ': 'Arrêter ',
  'No freeze: the figures shown are calculated at each consultation.': 'Aucun arrêté : les chiffres affichés sont calculés à chaque consultation.',
  'Annual freezes of the social indicators': 'Arrêtés annuels des indicateurs sociaux',
  'Freeze': 'Arrêté',
  'Reason: ': 'Motif : ',
  'At the CSE': 'Au CSE',
  'In force': 'En vigueur',
  'See the BDESE': 'Voir la BDESE',
  'Change the date of the CSE': 'Changer la date du CSE',
  'Made available to the CSE': 'Mis à disposition du CSE',
  'The freeze fixes the aggregates of a closed year, already masked, by grouping (overall, sex, category, status, contract; never the team), with the threshold and the version of the rules: the retention purges (time 3 years, files 5 years) and the corrections no longer change the figures of N-2 presented to the CSE. It is never deleted: it is cancelled with a reason (HR only, never in the log). The CSE has no access to Cursus: print or export the BDESE, file it, then note the date it was made available. ': 'L’arrêté fige les agrégats d’une année close, déjà masqués, par groupement (ensemble, sexe, catégorie, statut, contrat ; jamais l’équipe), avec le seuil et la version des règles : les purges de conservation (temps 3 ans, dossiers 5 ans) et les corrections ne changent plus les chiffres de N-2 présentés au CSE. Il n’est jamais supprimé : il s’annule avec un motif (service RH seulement, jamais au journal). Le CSE n’a pas d’accès à Cursus : imprimez ou exportez la BDESE, déposez-la, puis notez la date de mise à disposition. ',
  'Freeze or cancel: HR administrator.': 'Arrêter ou annuler : administrateur RH.',
  ': freeze no. ': ' : arrêté n° ',
  ' in force.': ' en vigueur.',
  ' is not over: it can only be frozen from 1 January ': ' n’est pas terminée : elle ne s’arrête qu’à partir du 1er janvier ',
